 * @param {string} issueDate
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string}
 */
function calculateDueDate(issueDate, terms) {
  switch (terms) {
    case 'NET14':
      return addDays(issueDate, 14);
    case 'NET30':
      return addDays(issueDate, 30);
    case 'EOM':
      return endOfMonth(issueDate);
    default:
      return null;
  }
}

/**
 * Validate payment terms.
 * @param {string} terms
 * @returns {{ ok: boolean }}
 */
function validateTerms(terms) {
  if (!['NET14', 'NET30', 'EOM'].includes(terms)) {
    return { ok: false };
  }
  return { ok: true };
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} param
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms?: string, dueDate?: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  const customer = customerResult.value;

  // Validate issueDate format and reality
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate terms
  const termsValidation = validateTerms(terms);
  if (!termsValidation.ok) {
    return fail('TERMS_INVALID');
  }

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discountPercent if provided
    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) {
      return discountValidation;
    }

    // Validate SKU
    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return productResult;
    }

    const product = productResult.value;
    const enrichedLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Apply discount: line's own discountPercent wins, otherwise use tier discount
    if (line.discountPercent !== undefined) {
      enrichedLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
      if (tierDiscount > 0) {
