import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { isValidDate, addDays, endOfMonth } from './dates.js';

/**
 * Calculate the due date based on terms and issue date.
 * @param {string} issueDate
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string}
 */
function calculateDueDate(issueDate, terms) {
  switch (terms) {
    case 'NET14':
      return addDays(issueDate, 14);
    case 'NET30':
      return addDays(issueDate, 30);
    case 'EOM':
      return endOfMonth(issueDate);
    default:
      return null;
  }
}

/**
 * Validate payment terms.
 * @param {string} terms
 * @returns {{ ok: boolean }}
 */
function validateTerms(terms) {
  if (!['NET14', 'NET30', 'EOM'].includes(terms)) {
    return { ok: false };
  }
  return { ok: true };
}

/**
 * Create a new invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} param
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms?: string, dueDate?: string } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines, terms = 'NET30' }) {
  // Normalize customer ID
  const normalizedCustomerId = normalizeId(customerId);

  // Validate customer exists
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  const customer = customerResult.value;

  // Validate issueDate format and reality
  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  // Validate terms
  const termsValidation = validateTerms(terms);
  if (!termsValidation.ok) {
    return fail('TERMS_INVALID');
  }

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    // Validate discountPercent if provided
    const discountValidation = validateDiscount(line.discountPercent);
    if (!discountValidation.ok) {
      return discountValidation;
    }

    // Validate SKU
    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return productResult;
    }

    const product = productResult.value;
    const enrichedLine = {
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
    };

    // Apply discount: line's own discountPercent wins, otherwise use tier discount
    if (line.discountPercent !== undefined) {
      enrichedLine.discountPercent = line.discountPercent;
    } else {
      const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
      if (tierDiscount > 0) {
        enrichedLine.discountPercent = tierDiscount;
      }
    }

    enrichedLines.push(enrichedLine);
  }

  const dueDate = calculateDueDate(issueDate, terms);
  const invoice = {
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
    terms,
    dueDate,
  };

  return ok(invoice);
}

/**
 * Calculate the total for a single line: qty × unitPrice (in cents).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, vatRate?: number, discountPercent?: number }>, voucher?: { amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);

  const discount = invoice.lines.reduce((sum, line) => {
    const lt = lineTotal(line);
    const lineDiscount = Math.floor(lt * (line.discountPercent ?? 0) / 100);
    return sum + Math.max(0, lineDiscount);
  }, 0);

  const vat = invoice.lines.reduce((sum, line) => {
    const lt = lineTotal(line);
    const lineDiscount = Math.floor(lt * (line.discountPercent ?? 0) / 100);
    const amountAfterDiscount = Math.max(0, lt - lineDiscount);
    const lineVat = Math.round(amountAfterDiscount * (line.vatRate ?? 0) / 100);
    return sum + Math.max(0, lineVat);
  }, 0);

  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

/**
 * Add or update a line on a draft invoice.
 * If SKU already exists, increases its qty; otherwise adds a new line.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array, terms?: string, dueDate?: string }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} param
 * @returns {{ ok: true, value: { ... } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

