import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, lineTotal, invoiceTotals, addLine, removeLine, issueInvoice, applyVoucher } from '../src/invoices.js';
import { nextInvoiceNumber } from '../src/numbering.js';

test('createInvoice creates a draft invoice with enriched lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });
  assert.equal(result.ok, true);
  const invoice = result.value;
  assert.equal(invoice.customerId, 'C-001');
  assert.equal(invoice.issueDate, '2026-10-07');
  assert.equal(invoice.status, 'draft');
  assert.equal(invoice.lines.length, 1);
  assert.equal(invoice.lines[0].sku, 'DES-HOUR');
  assert.equal(invoice.lines[0].name, 'Design work (hour)');
  assert.equal(invoice.lines[0].qty, 5);
  assert.equal(invoice.lines[0].unitPrice, 8500);
  assert.equal(invoice.lines[0].vatRate, 21);
});

test('createInvoice with multiple lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 3 },
      { sku: 'DEV-HOUR', qty: 2 },
    ],
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.lines.length, 2);
  assert.equal(result.value.lines[0].name, 'Design work (hour)');
  assert.equal(result.value.lines[1].name, 'Development (hour)');
});

test('createInvoice reports CUSTOMER_NOT_FOUND', () => {
  const result = createInvoice({
    customerId: 'NOPE',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('createInvoice reports DATE_INVALID for wrong format', () => {
  const testCases = [
    '10-07-2026',
    '2026/10/07',
    '2026-1-7',
    '2026-10-7',
    'not-a-date',
    '2026-13-01',
    '2026-12-32',
  ];
  for (const dateStr of testCases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, false, `Should reject ${dateStr}`);
    assert.equal(result.error, 'DATE_INVALID');
  }
});

test('createInvoice accepts valid dates', () => {
  const validDates = [
    '2026-01-01',
    '2026-12-31',
    '2024-02-29', // leap year
    '2025-02-28', // non-leap year
  ];
  for (const dateStr of validDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, true, `Should accept ${dateStr}`);
  }
});

test('createInvoice reports DATE_INVALID for invalid dates', () => {
  const invalidDates = [
    '2025-02-29', // non-leap year
    '2026-04-31', // April has 30 days
  ];
  for (const dateStr of invalidDates) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: dateStr,
      lines: [{ sku: 'DES-HOUR', qty: 1 }],
    });
    assert.equal(result.ok, false, `Should reject ${dateStr}`);
    assert.equal(result.error, 'DATE_INVALID');
  }
});

test('createInvoice reports NO_LINES for empty lines array', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [],
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports NO_LINES for missing lines', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: null,
  });
  assert.deepEqual(result, { ok: false, error: 'NO_LINES' });
});

test('createInvoice reports QTY_INVALID for non-integer qty', () => {
  const testCases = [1.5, '5', NaN, Infinity];
  for (const qty of testCases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty }],
    });
    assert.equal(result.ok, false, `Should reject qty ${qty}`);
    assert.equal(result.error, 'QTY_INVALID');
  }
});

test('createInvoice reports QTY_INVALID for zero or negative qty', () => {
  const testCases = [0, -1, -100];
  for (const qty of testCases) {
    const result = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-10-07',
      lines: [{ sku: 'DES-HOUR', qty }],
    });
    assert.equal(result.ok, false, `Should reject qty ${qty}`);
    assert.equal(result.error, 'QTY_INVALID');
  }
});

test('createInvoice reports UNKNOWN_SKU', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'NOPE', qty: 1 }],
  });
  assert.deepEqual(result, { ok: false, error: 'UNKNOWN_SKU' });
});

test('createInvoice does not mutate input', () => {
  const inputLines = [{ sku: 'DES-HOUR', qty: 5 }];
  const originalLine = { ...inputLines[0] };
  createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: inputLines,
  });
  assert.deepEqual(inputLines[0], originalLine);
});

test('createInvoice stops at first error', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'NOPE', qty: 0 }, // Both SKU unknown and qty invalid
    ],
  });
  // Should report QTY_INVALID since it checks qty before SKU in the second line
  assert.equal(result.error, 'QTY_INVALID');
});

test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 5, unitPrice: 8500 }), 42500);
  assert.equal(lineTotal({ qty: 1, unitPrice: 1000 }), 1000);
  assert.equal(lineTotal({ qty: 10, unitPrice: 50 }), 500);
  assert.equal(lineTotal({ qty: 100, unitPrice: 0 }), 0);
});

test('lineTotal returns cents (integers)', () => {
  const total = lineTotal({ qty: 3, unitPrice: 1000 });
  assert.ok(Number.isInteger(total));
  assert.equal(total, 3000);
});

test('invoiceTotals sums line totals for single line', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 42500);
  assert.equal(totals.total, 42500);
});

test('invoiceTotals sums line totals for multiple lines', () => {
  const invoice = {
    lines: [
      { qty: 3, unitPrice: 8500 },
      { qty: 2, unitPrice: 9500 },
      { qty: 1, unitPrice: 6000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expected = 3 * 8500 + 2 * 9500 + 1 * 6000;
  assert.equal(totals.subtotal, expected);
  assert.equal(totals.total, expected);
});

test('invoiceTotals with enriched invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 3 },
    ],
  });
  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  const subtotal = 2 * 8500 + 3 * 9500; // 45500
  const line1Vat = Math.round(17000 * 21 / 100); // 3570
  const line2Vat = Math.round(28500 * 21 / 100); // 5985
  const totalVat = line1Vat + line2Vat; // 9555

  assert.equal(totals.subtotal, 45500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 9555);
  assert.equal(totals.total, 45500 + 9555);
});

test('invoiceTotals with empty lines', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals returns integers', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 2, unitPrice: 1000 },
    ],
  };
  const totals = invoiceTotals(invoice);
  assert.ok(Number.isInteger(totals.subtotal));
  assert.ok(Number.isInteger(totals.total));
});

test('invoiceTotals does not mutate input', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 8500 },
      { qty: 2, unitPrice: 9500 },
